<?= $this->extend('layout') ?><?= $this->section('content') ?><div class="d-flex justify-content-between mb-3"><h1>Katalog Produk</h1><a href="/products/new" class="btn btn-primary">Tambah Produk</a></div><div class="card"><div class="card-body table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Produk</th><th>Harga Modal</th><th>Harga Jual</th><th>Toko/PIC</th><th>Aksi</th></tr></thead><tbody><?php foreach ($products as $row): ?><tr><td><strong><?= esc($row['name']) ?></strong><br><small><?= esc($row['sku'] ?? '') ?> <?= esc($row['brand'] ?? '') ?></small><?php if ($row['datasheet']): ?><br><small class="text-info">Datasheet tersedia</small><?php endif; ?></td><td>Rp <?= number_format((float)$row['cost_price'], 0, ',', '.') ?></td><td>Rp <?= number_format((float)$row['selling_price'], 0, ',', '.') ?></td><td><?= esc($row['store_name'] ?? '-') ?><br><small><?= esc($row['store_phone'] ?? '') ?></small><?php if ($row['store_url']): ?><br><a href="<?= esc($row['store_url']) ?>" target="_blank" rel="noopener">Buka link toko</a><?php endif; ?></td><td><a class="btn btn-sm btn-outline-secondary" href="/products/<?= $row['id'] ?>/edit">Edit</a> <form class="d-inline" method="post" action="/products/<?= $row['id'] ?>/delete" onsubmit="return confirm('Hapus produk ini?')"><button class="btn btn-sm btn-outline-danger">Hapus</button></form></td></tr><?php endforeach; ?></tbody></table></div></div><?= $this->endSection() ?>
